   202  xmlXPathObjectPtr
   203  xsltFuzzXPath(const char *data, size_t size) {
   204      xmlXPathContextPtr xpctxt = tctxt->xpathCtxt;
   205      xmlChar *xpathExpr;
   206
   207      /* Null-terminate */
   208      xpathExpr = malloc(size + 1);
   209      memcpy(xpathExpr, data, size);
   210      xpathExpr[size] = 0;
   211
   212      /*
   213       * format-number() can still cause memory errors with invalid UTF-8 in
   214       * prefixes or suffixes. This shouldn't be exploitable in practice, but
   215       * should be fixed. Check UTF-8 validity for now.
   216       */
   217      if (xmlCheckUTF8(xpathExpr) == 0) {
   218          free(xpathExpr);
   219          return NULL;
   220      }
   221
   222      /* Compile and return early if the expression is invalid */
   223      xmlXPathCompExprPtr compExpr = xmlXPathCtxtCompile(xpctxt, xpathExpr);
   224      free(xpathExpr);
   225      if (compExpr == NULL)
   226          return NULL;
   227
   228      /* Initialize XPath evaluation context and evaluate */
   229      xpctxt->node = (xmlNodePtr) doc; /* Maybe test different context nodes? */
   230      xpctxt->contextSize = 1;
   231      xpctxt->proximityPosition = 1;
   232      xpctxt->opCount = 0;
   233      xmlXPathObjectPtr xpathObj = xmlXPathCompiledEval(compExpr, xpctxt);
   234      xmlXPathFreeCompExpr(compExpr);
   235
   236      /* Clean object cache */
   237      xmlXPathContextSetCache(xpctxt, 0, 0, 0);
   238      xmlXPathContextSetCache(xpctxt, 1, -1, 0);
   239
   240      /* Clean dictionaries */
   241      if (xmlDictSize(tctxt->dict) > 0) {
   242          xmlDictFree(tctxt->dict);
   243          xmlDictFree(tctxt->style->dict);
   244          tctxt->style->dict = xmlDictCreate();
   245          tctxt->dict = xmlDictCreateSub(tctxt->style->dict);
   246      }
